        Path there = Path.of("there.txt");
        Files.writeString(there, "ある\n");

        for (String name : new String[] {"there.txt", "nothing.txt"}) {
            Path p = Path.of(name);
            try {
                System.out.print(name + " -> " + Files.readString(p));
            } catch (NoSuchFileException e) {
                System.out.println(name + " -> " + e.getClass().getSimpleName());
            }
        }
    }
}

